SELECT s1."c0" AS "id", s1."c1" AS "doubled" FROM (SELECT s2."c3" AS "c0", s2."c4" AS "c1" FROM (SELECT s3."c0" AS "c0", s3."c1" AS "c1", s3."c2" AS "c2", s3."c0" AS "c3", IFF((CAST(s3."c2" AS NUMBER(38,0)) * 2) BETWEEN -9223372036854775808 AND 9223372036854775807, (CAST(s3."c2" AS NUMBER(38,0)) * 2), CAST('sverify: integer overflow: ' || TO_VARCHAR((CAST(s3."c2" AS NUMBER(38,0)) * 2)) AS NUMBER(38,0))) AS "c4" FROM (SELECT s4."c0" AS "c0", s4."c1" AS "c1", s4."c2" AS "c2" FROM (SELECT "id" AS "c0", "customer" AS "c1", "amount" AS "c2" FROM "orders") AS s4 WHERE COALESCE((10 < s4."c2"), FALSE)) AS s3) AS s2) AS s1
